-- Generated by tools/island_builder.py. Edit the source data and rebuild instead.
local MAP_NAME = "gm_inf_island"
local DATA_PATH = "infmap2/" .. MAP_NAME .. "/terrain.bin"

local WIDTH = @@WIDTH@@
local HEIGHT = @@HEIGHT@@
local SAMPLE_COUNT = @@SAMPLE_COUNT@@
local ORIGIN_X = @@ORIGIN_X@@
local ORIGIN_Y = @@ORIGIN_Y@@
local STEP_X = @@STEP_X@@
local STEP_Y = @@STEP_Y@@
local SEA_LEVEL = @@SEA_LEVEL@@
local SEA_FLOOR = @@SEA_FLOOR@@

local raw = file.Read(DATA_PATH, "LUA")
if not raw then
    error("gm_inf_island: missing terrain data at " .. DATA_PATH)
end
if #raw ~= SAMPLE_COUNT * 2 then
    error("gm_inf_island: terrain data size does not match terrain.json")
end

local heights = {}
for index = 1, SAMPLE_COUNT do
    local byte_index = (index - 1) * 2 + 1
    local value = string.byte(raw, byte_index) + string.byte(raw, byte_index + 1) * 256
    if value >= 32768 then value = value - 65536 end
    heights[index] = value
end

local function sample_height(x, y)
    local grid_x = (x - ORIGIN_X) / STEP_X
    local grid_y = (y - ORIGIN_Y) / STEP_Y
    if grid_x < 0 or grid_y < 0 or grid_x > WIDTH - 1 or grid_y > HEIGHT - 1 then
        return SEA_FLOOR
    end

    local x0 = math.min(math.floor(grid_x), WIDTH - 2)
    local y0 = math.min(math.floor(grid_y), HEIGHT - 2)
    local tx = grid_x - x0
    local ty = grid_y - y0
    local top_left = heights[y0 * WIDTH + x0 + 1]
    local top_right = heights[y0 * WIDTH + x0 + 2]
    local bottom_left = heights[(y0 + 1) * WIDTH + x0 + 1]
    local bottom_right = heights[(y0 + 1) * WIDTH + x0 + 2]
    local top = top_left + (top_right - top_left) * tx
    local bottom = bottom_left + (bottom_right - bottom_left) * tx
    return top + (bottom - top) * ty
end

local function height_function(x, y)
    return sample_height(x, y)
end

if CLIENT then
    local water_material = Material("nature/water_coast01")
    local water_color = Color(255, 255, 255, 255)
    local water_size = 28000

    hook.Add("PostDrawTranslucentRenderables", "gm_inf_island_ocean", function(drawing_depth, drawing_skybox)
        if drawing_depth or drawing_skybox then return end
        local player = LocalPlayer()
        if not IsValid(player) then return end

        local position = player:GetPos()
        render.SetMaterial(water_material)
        render.DrawQuadEasy(
            Vector(position.x, position.y, SEA_LEVEL),
            Vector(0, 0, 1),
            water_size,
            water_size,
            water_color,
            0
        )
    end)
end

return {
    world = {
        terrain = {
            has_terrain = true,
            height_function = height_function,
        },
    },
    visual = {
        renderdistance = 2,
        terrain = {
            material = "nature/grassfloor001a",
            uvscale = 2048,
        },
    },
}
